sorting.routes:
- ALL main ids are UUIDs, NOT ints. Correct it if you find this type of error.
- Sort the paths by, in order of priority: a. Number of subpaths (ORDER BY ASC); b. Alphabetical order (ORDER BY ASC);
- When it comes to the alphabetical sorting, always put dynamic paths after static characters when you need to compare
		the same subpath depth;
- Keep the comments as they are

	Route::get('/allowanceoption', [AllowanceOptionController::class, 'index'])->name('allowanceoption.index');
	Route::get('/allowanceoption/create', [AllowanceOptionController::class, 'create'])->name('allowanceoption.create');
	Route::post('/allowanceoption/store', [AllowanceOptionController::class, 'store'])->name('allowanceoption.store');
	Route::delete('/allowanceoption/{allowanceoption}/delete', [AllowanceOptionController::class, 'destroy'])->name('allowanceoption.destroy');
	Route::get('/allowanceoption/{allowanceoption}/edit', [AllowanceOptionController::class, 'edit'])->name('allowanceoption.edit');
	Route::get('/allowanceoption/{allowanceoption}/show', [AllowanceOptionController::class, 'show'])->name('allowanceoption.show');
	Route::put('/allowanceoption/{allowanceoption}/update', [AllowanceOptionController::class, 'update'])->name('allowanceoption.update');
